import { join } from '@angular-devkit/core';
export const moduleNotFoundWarning = (name) => `No module found to register "${name}" in, so the application can't reach it yet. Add it to a module yourself, or pass --skip-import if that's intended.`;
export class ModuleFinder {
    tree;
    constructor(tree) {
        this.tree = tree;
    }
    find(options) {
        const generatedDirectoryPath = options.path;
        const generatedDirectory = this.tree.getDir(generatedDirectoryPath);
        const namedModuleFilename = options.name
            ? generatedDirectory.subfiles.find((filename) => filename === `${options.name}.module.ts` ||
                filename === `${options.name}.module.js`)
            : undefined;
        return namedModuleFilename !== undefined
            ? join(generatedDirectory.path, namedModuleFilename.valueOf())
            : this.findIn(generatedDirectory);
    }
    findIn(directory) {
        if (!directory) {
            return null;
        }
        const moduleFilename = directory.subfiles.find((filename) => /\.module\.(t|j)s$/.test(filename)) ?? this.findEntryFileDeclaringModule(directory);
        return moduleFilename !== undefined
            ? join(directory.path, moduleFilename.valueOf())
            : this.findIn(directory.parent);
    }
    findEntryFileDeclaringModule(directory) {
        return directory.subfiles.find((filename) => /^main\.(t|j)s$/.test(filename) &&
            /@Module\(\s*\{/.test(directory.file(filename).content.toString()));
    }
}
